SELECT  FROM reviewed_observation
WHERE owner_id=#{owner} AND session_id=#{sessionId} AND training_question_id=#{questionId} AND answer_id=#{answerId}
AND status=#{status}
AND id > #{cursor}
ORDER BY id ASC LIMIT #{pageSize}


SELECT  FROM reviewed_observation_revision
WHERE owner_id=#{owner} AND observation_id=#{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{pageSize}

mapper.update:
UPDATE reviewed_observation SET revision=#{row.revision},status=#{row.status},updated_at=#{row.updatedAt}
WHERE owner_id=#{row.ownerId} AND id=#{row.id} AND session_id=#{row.sessionId}
  AND training_question_id=#{row.questionId} AND answer_id=#{row.answerId} AND checkpoint_id=#{row.checkpointId}
  AND revision=#{expected} AND status='ACTIVE' AND #{expected} < 9007199254740991
  AND #{row.revision}=revision+1 AND #{row.updatedAt} >= updated_at
